    <style>
        :root{--bg:#07110f;--panel:#0d1c18;--line:#26483f;--muted:#8ba79f;--text:#edf7f3;--green:#5dd6ad}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.layout{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:26px 18px;border-right:1px solid #1e3932;background:#091713}.brand{display:flex;align-items:center;gap:11px;padding:0 8px 28px}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#16372e;color:var(--green)}.brand strong{font-size:14px}.nav-label{padding:0 10px;margin:16px 0 7px;color:#5f8177;font-size:10px;text-transform:uppercase;letter-spacing:.13em}.nav-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:10px;color:#91aea5;text-decoration:none;font-size:13px}.nav-item.active{background:#153129;color:#eafff7}.nav-item:hover{color:#fff;background:#10251f}.sidebar-foot{position:absolute;left:18px;right:18px;bottom:20px}.logout{width:100%;padding:10px;border:1px solid #2a4a41;border-radius:10px;background:transparent;color:#a9c3bb;cursor:pointer}.queue-open{width:100%;margin-bottom:8px;padding:11px 12px;display:flex;align-items:center;justify-content:space-between;border:1px solid #31584d;border-radius:10px;background:#10251f;color:#c9e3db;cursor:pointer}.queue-count{min-width:23px;padding:3px 7px;border-radius:999px;background:var(--green);color:#062219;font-size:10px;font-weight:800}.drawer-overlay{position:fixed;inset:0;background:#0008;opacity:0;visibility:hidden;transition:.25s;z-index:20}.drawer-overlay.open{opacity:1;visibility:visible}.queue-drawer{position:fixed;z-index:21;top:0;right:0;width:min(430px,100%);height:100vh;padding:25px;background:#091713;border-left:1px solid var(--line);box-shadow:-20px 0 60px #0008;transform:translateX(100%);transition:transform .3s;overflow:auto}.queue-drawer.open{transform:none}.drawer-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:22px}.drawer-head h2{margin:0;font-size:18px}.drawer-head p{margin:5px 0 0;color:var(--muted);font-size:11px}.drawer-close{width:34px;height:34px;border:1px solid #31584d;border-radius:50%;background:transparent;color:#b7d3ca;cursor:pointer}.queue-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:18px}.queue-stat{padding:12px;border:1px solid #203d35;border-radius:10px;background:#0d1c18}.queue-stat span{display:block;color:#698a80;font-size:9px;text-transform:uppercase}.queue-stat strong{display:block;margin-top:5px;font-size:18px}.live-card{padding:14px;margin-bottom:10px;border:1px solid #25463d;border-radius:12px;background:#0d1c18}.live-top{display:flex;justify-content:space-between;gap:10px}.live-name{font-size:12px;font-weight:750}.live-state{color:var(--green);font-size:10px}.live-meta{margin-top:8px;color:var(--muted);font-size:10px;line-height:1.6}.live-progress{height:5px;margin-top:10px;border-radius:8px;background:#172e27;overflow:hidden}.live-progress i{display:block;height:100%;width:38%;border-radius:8px;background:var(--green);animation:pulse 1.4s ease-in-out infinite}@keyframes pulse{50%{opacity:.35;transform:translateX(130%)}}.drawer-tabs{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:14px}.drawer-tab{padding:9px;border:1px solid #294b42;border-radius:9px;background:transparent;color:#86a79d;cursor:pointer}.drawer-tab.active{background:#17382f;color:#dffff4;border-color:#43816e}.drawer-pane{display:none}.drawer-pane.active{display:block}.drawer-refresh{margin-left:auto;padding:6px 9px;border:1px solid #31584d;border-radius:7px;background:transparent;color:#9ec2b7;cursor:pointer}.completed-card{padding:13px;margin-bottom:9px;border:1px solid #25463d;border-radius:11px;background:#0d1c18}.completed-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:10px}.completed-date{color:#789a90;font-size:10px}.drawer-empty{padding:35px;text-align:center;color:var(--muted);font-size:11px}.main{min-width:0;padding:34px clamp(22px,4vw,58px) 60px;background-image:radial-gradient(circle at 85% 0,#15382f 0,transparent 25%)}h1{margin:0 0 24px;font-size:25px;letter-spacing:-.04em}.panel{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--panel)}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;text-align:left;border-bottom:1px solid #19332c;font-size:12px}th{color:#789a90;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.empty{padding:64px 20px;text-align:center;color:var(--muted)}.empty-icon{display:grid;place-items:center;width:44px;height:44px;margin:0 auto 14px;border:1px solid #31564c;border-radius:50%;color:var(--green)}.empty strong{display:block;margin-bottom:6px;color:#dceee8;font-size:14px}.empty span{font-size:12px}.status{display:inline-flex;padding:5px 9px;border-radius:999px;background:#192c27;color:#78978e}.action{padding:7px 10px;border:1px solid #2c4c43;border-radius:8px;background:transparent;color:#66847b}@media(max-width:760px){.layout{display:block}.sidebar{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.sidebar .nav-label,.sidebar-foot{display:none}.main{padding:25px 16px}.panel{overflow:auto}table{min-width:620px}}
        .history{width:100%;border:1px solid #213e36;border-radius:10px;overflow:hidden}.history-row{display:grid;grid-template-columns:150px 1fr 140px 110px;gap:10px;align-items:center;padding:10px 12px;border-bottom:1px solid #19332c;font-size:11px}.history-row:last-child{border-bottom:0}.history-run{display:flex;align-items:center;gap:7px}.run-status{display:inline-flex;padding:4px 7px;border-radius:999px;font-size:9px}.run-status.success{background:#173c31;color:#7ce5bf}.run-status.failed{background:#432523;color:#f0a59d}.run-status.running{background:#34321d;color:#eadb8c}.history-meta{color:var(--muted)}.export{display:inline-block;padding:7px 9px;border:1px solid #34715f;border-radius:7px;color:#9ceaca;text-decoration:none;text-align:center}@media(max-width:760px){.history-row{grid-template-columns:1fr}}
        .history-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px}.history-head h3{margin:0}.confirm-overlay{position:fixed;inset:0;z-index:40;display:grid;place-items:center;padding:20px;background:#000a;opacity:0;visibility:hidden;transition:.2s}.confirm-overlay.open{opacity:1;visibility:visible}.confirm-box{width:min(420px,100%);padding:22px;border:1px solid #31584d;border-radius:15px;background:#0d1c18;box-shadow:0 24px 70px #000b;transform:translateY(8px);transition:.2s}.confirm-overlay.open .confirm-box{transform:none}.confirm-box h2{margin:0 0 8px;font-size:17px}.confirm-box p{margin:0;color:var(--muted);font-size:12px;line-height:1.6}.confirm-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.confirm-danger{border-color:#75443f;color:#f0a59d}
        .toggle{width:34px;height:34px;flex:0 0 34px;padding:0;display:grid;place-items:center;border:1px solid #31584d;border-radius:50%;background:#10251f;color:#a8cec2;cursor:pointer;transition:background .2s,border-color .2s,color .2s,transform .25s}.toggle:hover{background:#18352d;border-color:#4c8b78;color:#e5fff7}.toggle svg{width:15px;height:15px;transition:transform .3s ease}.toggle.open svg{transform:rotate(180deg)}.detail-row td{padding:0;border-bottom:1px solid #26483f}.detail{max-height:0;overflow:hidden;background:#091713;transition:max-height .42s ease}.detail.open{max-height:720px}.detail-content{padding:22px 24px 26px;display:grid;grid-template-columns:1.2fr 1fr;gap:28px}.detail h3{margin:0 0 9px;font-size:13px}.detail p{margin:0;color:var(--muted);font-size:12px;line-height:1.65}.flow{display:flex;align-items:center;flex-wrap:wrap;gap:7px;margin-top:15px}.step{padding:7px 9px;border:1px solid #284a41;border-radius:8px;color:#b9d4cc;font-size:11px}.arrow{color:#52766b}.facts{display:grid;grid-template-columns:1fr 1fr;gap:9px}.fact{padding:11px;border:1px solid #213e36;border-radius:9px}.fact span{display:block;color:#698a80;font-size:9px;text-transform:uppercase;letter-spacing:.08em}.fact strong{display:block;margin-top:5px;font-size:11px}.fields{grid-column:1/-1}.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{padding:5px 8px;border-radius:6px;background:#10251f;color:#8fb4a9;font:10px ui-monospace,SFMono-Regular,monospace}@media(max-width:760px){.detail-content{grid-template-columns:1fr}.fields{grid-column:auto}}
    </style>
