    <div class="confirm-overlay" id="reports-clear-modal"><div class="confirm-box" role="dialog" aria-modal="true" aria-labelledby="reports-clear-title"><h2 id="reports-clear-title">Limpar relatórios?</h2><p id="reports-clear-message"></p><div class="confirm-actions"><button class="action" id="reports-clear-cancel" type="button" style="cursor:pointer">Cancelar</button><button class="action confirm-danger" id="reports-clear-confirm" type="button" style="cursor:pointer">Sim, limpar</button></div></div></div>
</div><div class="drawer-overlay" id="drawer-overlay"></div><aside class="queue-drawer" id="queue-drawer"><div class="drawer-head"><div><h2>Central de execu&ccedil;&atilde;o</h2><p>Fila, conclu&iacute;dos e relat&oacute;rios em tempo real</p></div><button class="drawer-close" id="drawer-close" type="button">&times;</button></div><div class="drawer-tabs"><button class="drawer-tab active" type="button" data-pane="live">Em andamento</button><button class="drawer-tab" type="button" data-pane="completed">Conclu&iacute;dos <span id="completed-count"></span></button></div><section class="drawer-pane active" id="pane-live"><div class="queue-summary"><div class="queue-stat"><span>Total</span><strong id="queue-total">0</strong></div><div class="queue-stat"><span>Executando</span><strong id="queue-running">0</strong></div><div class="queue-stat"><span>Aguardando</span><strong id="queue-waiting">0</strong></div></div><div id="queue-live"></div></section><section class="drawer-pane" id="pane-completed"><div style="display:flex;align-items:center;margin-bottom:12px"><span style="color:var(--muted);font-size:11px">20 execu&ccedil;&otilde;es mais recentes</span><button class="drawer-refresh" id="drawer-refresh" type="button">Atualizar</button><form method="POST" action="{{ route('admin.services.runs.clear-completed') }}" onsubmit="return confirm('Limpar todo o histrico concludo? Os dados sincronizados no sero apagados.')">@csrf<button class="drawer-refresh" type="submit" style="color:#f0a59d;border-color:#75443f">Limpar concludas</button></form></div><div id="completed-live"></div></section></aside><script>
document.querySelectorAll('.toggle').forEach(button=>button.addEventListener('click',()=>{const panel=document.getElementById(button.dataset.detail);const open=panel.classList.toggle('open');button.classList.toggle('open',open);button.setAttribute('aria-expanded',open?'true':'false')}));
const reportsModal=document.getElementById('reports-clear-modal'),reportsMessage=document.getElementById('reports-clear-message');let pendingReportsForm=null;const closeReportsModal=()=>{reportsModal.classList.remove('open');pendingReportsForm=null};document.querySelectorAll('[data-clear-reports]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();pendingReportsForm=form;reportsMessage.textContent='Os relatórios concluídos de '+form.dataset.serviceName+' serão removidos. Os dados sincronizados não serão apagados.';reportsModal.classList.add('open')}));document.getElementById('reports-clear-cancel').onclick=closeReportsModal;document.getElementById('reports-clear-confirm').onclick=()=>{if(!pendingReportsForm)return;const form=pendingReportsForm;closeReportsModal();form.submit()};reportsModal.addEventListener('click',event=>{if(event.target===reportsModal)closeReportsModal()});
const duration=s=>{if(s===null)return '—';const h=Math.floor(s/3600),m=Math.floor((s%3600)/60),x=s%60;return h?`${h}h ${m}min`:(m?`${m}min ${x}s`:`${x}s`)};
let liveData={services:[],completed:[],queue:{total:0,running:0,waiting:0,jobs:[]}};
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const localDate=value=>value?new Date(value).toLocaleString('pt-BR'):'-';
const runTables=run=>{const rows=Object.entries(run.new_records_by_resource||{}).filter(([,total])=>total>0).map(([resource,total])=>escapeHtml(resource)+': '+total+' novos');return rows.join(' &middot; ')||(run.status==='running'?'Aguardando inserções novas':'Nenhuma inserção nova')};
function renderDrawer(){
 const q=liveData.queue;
 document.getElementById('queue-count').textContent=q.total;
 document.getElementById('queue-total').textContent=q.total;
 document.getElementById('queue-running').textContent=q.running;
 document.getElementById('queue-waiting').textContent=q.waiting;
 document.getElementById('completed-count').textContent='('+liveData.completed.length+')';
 const running=liveData.services.filter(s=>s.run?.status==='running').map(s=>'<article class="live-card"><div class="live-top"><span class="live-name">'+escapeHtml(s.name)+'</span><span class="live-state">Executando &middot; '+duration(s.run.duration_seconds)+'</span></div><div class="live-meta">'+runTables(s.run)+'</div><div class="live-progress"><i></i></div></article>');
 const jobs=q.jobs.filter(j=>j.status==='waiting').map(j=>'<article class="live-card"><div class="live-top"><span class="live-name">'+escapeHtml(j.name)+'</span><span class="live-state">Na fila</span></div><div class="live-meta">Fila '+escapeHtml(j.queue)+' &middot; aguardando '+duration(j.waiting_seconds)+'</div></article>');
 document.getElementById('queue-live').innerHTML=[...running,...jobs].join('')||'<div class="drawer-empty">Fila vazia. Nenhum service em execu&ccedil;&atilde;o.</div>';
 document.getElementById('completed-live').innerHTML=liveData.completed.map(run=>'<article class="completed-card"><div class="live-top"><span class="live-name">#'+run.id+' &middot; '+escapeHtml(run.service_name)+'</span><span class="live-state">'+(run.status==='success'?'Concluída':'Falhou')+'</span></div><div class="live-meta">'+runTables(run)+'<br>Tempo: '+duration(run.duration_seconds)+'</div><div class="completed-actions"><span class="completed-date">'+localDate(run.finished_at)+'</span><a class="export" href="'+escapeHtml(run.export_url)+'">Gerar relatório Excel</a></div></article>').join('')||'<div class="drawer-empty">Nenhuma execução concluída.</div>';
}
function renderReportHistories(){
 liveData.services.forEach(service=>{const history=document.querySelector('#service-'+service.id+' .history');if(!history)return;const runs=liveData.completed.filter(run=>run.service_id===service.id).slice(0,5);history.innerHTML=runs.map(run=>'<div class="history-row"><strong class="history-run"><span>#'+run.id+'</span><span class="run-status '+escapeHtml(run.status)+'">'+(run.status==='success'?'Concluída':'Falhou')+'</span></strong><span class="history-meta">'+localDate(run.started_at)+' &middot; '+runTables(run)+'</span><span>'+duration(run.duration_seconds)+'</span><a class="export" href="'+escapeHtml(run.export_url)+'">Exportar Excel</a></div>').join('')||'<div style="padding:14px;color:var(--muted);font-size:11px">Nenhuma execução registrada.</div>'});
}
async function refreshServices(){
 try{
  const response=await fetch(@json(route('admin.services.status'))+'?t='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});
  if(!response.ok)return;
  const data=await response.json();liveData=data;
  data.services.forEach(service=>{
   const row=document.querySelector('[data-service-id="'+service.id+'"]');if(!row)return;
   const badge=row.querySelector('[data-role=service-status]');badge.textContent=service.active?'Ativo':'Pausado';badge.style=service.active?'background:#173c31;color:#7ce5bf':'';
   const target=row.querySelector('[data-role=run-progress]'),run=service.run;
   if(!run){target.innerHTML='<span style="color:var(--muted)">Nunca executado</span>';return}
   target.innerHTML='<strong>'+localDate(run.started_at)+'</strong>';
  });renderDrawer();renderReportHistories();
 }catch(e){}
}
const drawer=document.getElementById('queue-drawer'),overlay=document.getElementById('drawer-overlay');const closeDrawer=()=>{drawer.classList.remove('open');overlay.classList.remove('open')};document.getElementById('queue-open').onclick=()=>{drawer.classList.add('open');overlay.classList.add('open');refreshServices()};document.getElementById('drawer-close').onclick=closeDrawer;document.querySelectorAll('.drawer-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.drawer-tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.drawer-pane').forEach(pane=>pane.classList.toggle('active',pane.id==='pane-'+tab.dataset.pane));if(tab.dataset.pane==='completed')refreshServices()}));document.getElementById('drawer-refresh').onclick=refreshServices;overlay.onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
setInterval(()=>{liveData.services.forEach(s=>{if(s.run?.status==='running')s.run.duration_seconds++});liveData.queue.jobs.forEach(j=>j.waiting_seconds++);renderDrawer()},1000);setInterval(refreshServices,3000);refreshServices();
</script></body></html>
